    "dataClasses": [],
    "exposure": "public",
    "llmFeatures": false
  },
  "threats": [
    {
      "stride": "InformationDisclosure",
      "title": "A leaked share link gives permanent access to the file because links never expire",
      "scenario": "Share links are the only access control and they live forever. An attacker who finds a link in a forwarded email, a chat archive, a browser history on a shared machine, or a ticket attachment can open the document months or years later. The uploader has no way to cut off access, so one leak is permanent exposure of that document to anyone the link reaches.",
