      "cwe": ["CWE-613"],
      "plainLanguage": "A share link works forever, so if it ever leaks the file is exposed for good and nobody can turn it off.",
      "requirement": {
        "title": "Share links must expire and be revocable",
        "given": "a user has created a public share link for an uploaded document",
        "when": "the link's expiry time passes or the owner revokes it",
        "then": "the link returns a generic 'not available' response and no file content or metadata is served"
      }
    },
    {
      "stride": "InformationDisclosure",
      "title": "Guessable share link identifiers let an attacker enumerate other people's documents",
      "scenario": "Because anyone with the link can view a file with no login, the link token is the whole secret. If identifiers are sequential, short, or derived from a filename or upload id, an attacker can script requests across the link space and harvest documents belonging to unrelated users, including anything sensitive users uploaded. There is no account to lock out and no owner check to stop the sweep.",
      "component": "Public file viewer",
      "likelihood": 3,
      "impact": 5,
      "evidence": [
        { "quote": "Users upload documents and share them through a public link. Anyone with the link can view the file without logging in." }
      ],
      "cwe": ["CWE-639", "CWE-340"],
      "plainLanguage": "If the link code is easy to guess, someone can try many codes and download strangers' documents.",
      "requirement": {
        "title": "Share tokens must be unguessable and enumeration must be throttled",
        "given": "the public file viewer serves a document for a share token",
        "when": "an anonymous client requests many tokens, including invalid ones",
        "then": "tokens are at least 128 bits from a cryptographically secure random source, invalid and valid tokens return indistinguishable errors for non-existent files, and repeated failed lookups from one source are throttled"
      }
    },
    {
      "stride": "ElevationOfPrivilege",
      "title": "Documents reachable directly from the S3 bucket, bypassing the share link entirely",
      "scenario": "Files are stored in an S3 bucket. If the bucket or objects are public-read, or if object URLs/keys are predictable, an attacker can request objects directly from S3 and skip the application's link check altogether. Public bucket listing would hand over an index of every uploaded document. Any expiry or revocation added later at the application layer would be bypassed the same way.",
      "component": "S3 bucket (uploaded documents)",
      "likelihood": 3,
      "impact": 5,
      "evidence": [
        { "quote": "Files are stored in an S3 bucket." }
