      "requirement": {
        "title": "S3 objects must only be reachable through the application",
        "given": "an uploaded document stored in the S3 bucket",
        "when": "a client requests the object directly from S3 without going through the share link flow",
        "then": "the request is denied because public access and listing are blocked and content is served only via short-lived pre-signed URLs or an application proxy that validated the share token"
      }
    },
    {
      "stride": "Tampering",
      "title": "Malicious uploads served back to viewers as active content",
      "scenario": "Anonymous viewers open uploaded documents in the browser. If the upload endpoint accepts any file type and the viewer serves it inline with an attacker-controlled content type, an attacker uploads HTML, SVG or JavaScript and sends the public link to victims. The script runs on the application's own origin, so it can read other content on that origin and present convincing phishing under the product's domain. The same channel distributes malware with a trusted-looking link.",
      "component": "File upload endpoint / public file viewer",
      "likelihood": 4,
      "impact": 4,
      "evidence": [
        { "quote": "Users upload documents and share them through a public link." }
      ],
      "cwe": ["CWE-434", "CWE-79"],
      "plainLanguage": "Someone can upload a web page or script instead of a document, and it runs in the browser of anyone who opens the link.",
      "requirement": {
        "title": "Uploaded files must be served as inert downloads from an isolated origin",
        "given": "an uploaded file whose declared type is attacker controlled",
        "when": "a viewer opens the public share link",
        "then": "the file is served from a separate domain with a server-determined content type, Content-Disposition: attachment for non-previewable types, X-Content-Type-Options: nosniff and a restrictive Content-Security-Policy, and HTML/SVG/script types are never rendered inline on the application origin"
      }
    },
    {
      "stride": "Spoofing",
      "title": "Unauthenticated upload turns the service into free hosting for phishing and malware",
      "scenario": "The design has no login anywhere in the sharing flow and does not state that uploading requires an account. An attacker uploads phishing pages or malware and distributes links that carry the reputation of the product's domain, with no account to suspend and no expiry to limit the campaign. The domain ends up on blocklists, harming all legitimate users.",
      "component": "File upload endpoint",
      "likelihood": 4,
      "impact": 3,
      "evidence": [
        { "quote": "Users upload documents and share them through a public link. Anyone with the link can view the file without logging in." }
      ],
      "cwe": ["CWE-306"],
      "plainLanguage": "If anyone can upload without an account, attackers will host scam files on your domain.",
      "requirement": {
        "title": "Uploads require an authenticated, attributable actor",
        "given": "a client calls the upload endpoint",
        "when": "the client has no authenticated session",
        "then": "the upload is rejected, and for authenticated uploads the owner identity is stored with the object and share link"
      }
    },
    {
      "stride": "DenialOfService",
      "title": "Unbounded uploads and unlimited public downloads drive storage and egress cost exhaustion",
      "scenario": "With no login on the sharing path and files kept in S3 forever, an attacker can push large or numerous files, then repeatedly fetch a single public link to generate S3 egress. Because nothing expires, nothing is ever reclaimed. The result is a billing-driven outage or forced shutdown of the feature rather than a classic traffic flood, which is why generic rate limiting is not enough here.",
      "component": "File upload endpoint / S3 bucket",
      "likelihood": 3,
      "impact": 3,
      "evidence": [
        { "quote": "Links never expire. Files are stored in an S3 bucket." }
      ],
      "cwe": ["CWE-770"],
      "plainLanguage": "Someone can upload huge files or download the same link endlessly and run up your storage bill until the feature has to be switched off.",
      "requirement": {
        "title": "Enforce per-actor size, count and retention limits on stored files",
        "given": "configured limits for file size, total storage per owner and retention period",
        "when": "an upload exceeds a limit or an object passes its retention period",
        "then": "the upload is rejected with a clear error, expired objects are deleted by lifecycle policy, and sustained download volume for a single share link is capped"
      }
    },
    {
      "stride": "InformationDisclosure",
      "title": "Public links indexed by search engines and leaked in Referer headers",
      "scenario": "Links that need no login are routinely crawled once pasted anywhere public, making private documents searchable. If the viewer page loads third-party resources or contains outbound links, the share token travels in the Referer header to those parties. Either path exposes the document to people the uploader never shared it with, and because links never expire the exposure cannot be undone.",
      "component": "Public file viewer",
      "likelihood": 3,
      "impact": 3,
      "evidence": [
        { "quote": "Users upload documents and share them through a public link." }
      ],
      "cwe": ["CWE-200"],
      "plainLanguage": "Search engines can index no-login links, and the secret part of the URL can leak to other sites as a referrer.",
      "requirement": {
        "title": "Prevent indexing and referrer leakage of share tokens",
        "given": "a public share link page or file response",
        "when": "a crawler fetches it or the viewer navigates to an external resource",
        "then": "responses send X-Robots-Tag: noindex, nofollow and Referrer-Policy: no-referrer, and the share token is not placed in a URL sent to third-party origins"
      }
    },
    {
      "stride": "Repudiation",
      "title": "No way to attribute who uploaded or viewed a shared document",
      "scenario": "With no login on either side of the flow, there is no identity bound to an upload or a view. When a document leaks or an abusive file is reported, the team cannot tell who uploaded it or how widely the link was accessed, so they cannot scope the incident or notify affected users, and an uploader can plausibly deny the action.",
      "component": "Share link redemption / upload endpoint",
      "likelihood": 3,
      "impact": 3,
      "evidence": [
        { "quote": "Anyone with the link can view the file without logging in." }
      ],
      "cwe": ["CWE-778"],
      "plainLanguage": "Because nobody logs in, you cannot tell who uploaded a file or who has opened it when something goes wrong.",
      "requirement": {
        "title": "Record attributable upload and access events per share link",
        "given": "an upload or a share link redemption",
        "when": "the event is processed",
        "then": "the system records the authenticated uploader identity, the share token id, timestamp and request source for each access, and exposes access history to the file owner"
      }
    }
  ]
}
